INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (1,'carta_folha','A Folha que Venceu','comum','Uma folha de caderno dobrada em origami de avião, atravessando a noite.','Dizem que no primeiro mês de treino, Gabi dobrou uma folha com 100 questões erradas e a fez voar até a FUVEST. O vento devolveu um bilhete: ''ainda não''.',1,'2026-08-02 16:22:53.894558',0);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (2,'carta_relogio','O Relógio de Ouro','comum','Um relógio de bolso dourado parado exatamente às 25:00.','Há um pomodoro que nunca termina: aquele que ela decide não começar. Este relógio marca a única derrota da operação — e por isso nunca mais foi visto.',1,'2026-08-02 16:22:53.894585',1);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (3,'carta_caderno','O Caderno Vivo','comum','Um caderno cujas páginas crescem galhos e folhas douradas.','Todo resumo escrito com verdade faz o caderno florescer. O caderno central da operação já é uma pequena floresta.',1,'2026-08-02 16:22:53.894590',2);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (4,'carta_caneta','A Caneta Tática','comum','Uma caneta preta com detalhes dourados, presa por uma corrente.','O equipamento oficial da operação. Nenhuma redação foi escrita sem ela; nenhum medo sobreviveu à tinta dela.',1,'2026-08-02 16:22:53.894594',3);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (5,'carta_biblioteca','A Biblioteca Silenciosa','rara','Uma biblioteca infinita sob a luz de uma lua dourada.','Cada livro estudado vira um corredor novo. Quem conhece todos os corredores chega à sala onde a FUVEST esconde as questões do ano.',2,NULL,4);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (6,'carta_pomodoro','O Tomate de Guerra','rara','Um tomate de metal dourado com engrenagens e um visor de contagem.','A arma mais simples e mais temida da operação: 25 minutos de silêncio absoluto. O inimigo? Tudo o que não é a aprovação.',2,NULL,5);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (7,'carta_flashcard','O Baralho da Memória','rara','Um baralho de cartas brilhando em neon, flutuando sobre a mesa.','Cada carta guarda uma ideia. Jogar o baralho certo na hora da prova é o segredo dos que saem sorrindo da sala.',2,NULL,6);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (8,'carta_questao','A Questão Espelho','rara','Uma questão que reflete quem a resolve.','Dizem que cada questão da FUVEST é um espelho: mostra não o que você sabe, mas o que você escolheu estudar nos últimos três anos.',2,NULL,7);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (9,'carta_prova','O Templo do Simulado','rara','Um templo futurista onde simulados são disputados sob holofotes dourados.','Sábado é dia de batalha. Os que sangram no templo não sangram na prova.',3,NULL,8);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (10,'carta_redacao','A Pena de Luz','épica','Uma pena que escreve com luz dourada sobre o ar.','Reza a lenda que apenas três redações nota mil foram escritas com ela. A quarta está sendo escrita agora, página por página.',3,NULL,9);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (11,'carta_revisao','O Guardião das Revisões','épica','Um guardião de pedra negra com olhos dourados, vigiando o portão da memória.','Ele não deixa nada ser esquecido. Quem passa pelo portão a cada 7 e 21 dias entra na prova com tudo na memória.',3,NULL,10);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (12,'carta_cidade','A Cidade Dourada','épica','Uma cidade futurista inteira acesa, vista do alto do distrito mais alto.','Cada distrito dominado acende um setor da cidade. Quando a cidade estiver toda acesa, as portas da FMUSP se abrem sozinhas.',4,NULL,11);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (13,'carta_fm','A Torre FMUSP','lendária','Uma torre de vidro e ouro cortando as nuvens no centro da cidade.','No topo da torre, uma sala com uma única cadeira. A cadeira tem o nome de quem atravessar os cinco distritos sem desistir.',5,NULL,12);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (14,'carta_estrela','A Estrela do Primeiro Dia','lendária','Uma estrela cadente dourada caindo sobre um caderno aberto no dia 01/07/2026.','No primeiro dia da operação, uma estrela caiu sobre o caderno de Gabi e sussurrou: ''os três anos mais importantes da sua vida começam agora'' — e virou a capa da missão.',1,'2026-08-02 16:22:53.894597',13);
INSERT INTO cards (id,slug,name,rarity,description,history,phase_unlock,unlocked_at,art_seed) VALUES (15,'carta_final','A Fase Final','lendária','Um portão de ouro se abrindo para um corredor de luz.','Só existe uma regra para atravessar: não deixar nada para trás. Todas as revisões feitas, todas as redações corrigidas, todas as cartas no baralho.',5,NULL,14);
INSERT INTO quotes (id,text,occasion) VALUES (1,'Cada questão dominada hoje é um quarteirão a mais no mapa da Medicina. A cidade inteira já sabe seu nome.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (2,'A FMUSP não quer a mais inteligente da sala. Quer a que não desistiu na terça-feira.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (3,'Enquanto a cidade dorme, seu caderno acende. É isso que separa quem sonha de quem passa.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (4,'Três anos parecem uma eternidade até o dia em que viram três segundos de resposta correta.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (5,'Você não está estudando. Você está construindo a versão de você que anda pelo campus em 2029.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (6,'O cansaço de hoje é o combustível que a aprovação de 2028 vai queimar.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (7,'Distrito Matemática não foi dominado em um dia. Foi dominado em domingos comuns, sem plateia.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (8,'A prova dura 4 horas. A preparação dura 3 anos. Quem faz as contas antes, chora depois — de felicidade.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (9,'A FUVEST não mede seu talento. Mede sua rotina sob pressão. Hoje é dia de treinar sob pressão.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (10,'Um dia sem revisão é uma rua que você esqueceu de iluminar na cidade.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (11,'Ela não sabe seu nome. Mas quando você assinar a lista de aprovados, ela vai olhar a folha duas vezes.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (12,'O frio na barriga antes do simulado é o mesmo de antes da prova real. Acostume-se a vencer com ele.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (13,'Nota não é sorte. É a soma de pomodoros que ninguém viu.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (14,'Cada flashcard revisado é um tijolo. A torre FMUSP é construída com 3.000 tijolos desses.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (15,'Hoje, escolha ser a versão de você que estuda sem precisar de motivação. Essa versão passa.','dia');
INSERT INTO quotes (id,text,occasion) VALUES (16,'A operação não acabou. Só pausou. E pausa não é derrota — é respiração antes do próximo distrito.','crise');
INSERT INTO quotes (id,text,occasion) VALUES (17,'Três dias de silêncio é o tempo que a dúvida leva para bater à porta. Responda a ela: 5 flashcards. 10 minutos. 3 questões. Volte.','crise');
INSERT INTO quotes (id,text,occasion) VALUES (18,'A cidade continuou acesa esperando você. Ela é paciente, mas o cronograma não.','crise');
INSERT INTO quotes (id,text,occasion) VALUES (19,'Você não perdeu a sequência. Você só deixou uma mensagem de voz — agora é hora de atender.','crise');
INSERT INTO quotes (id,text,occasion) VALUES (20,'Ninguém chegou à FMUSP sem um dia de chuva. A diferença é que o agente volta ao posto. Você volta.','crise');
INSERT INTO quotes (id,text,occasion) VALUES (21,'Fase 1 concluída: o hábito nasceu. Agora ele precisa de alimento diário — e você já sabe o cardápio.','fase1');
INSERT INTO quotes (id,text,occasion) VALUES (22,'Você não construiu uma rotina. Você construiu um reflexo. Os reflexos não falham em dia de prova.','fase1');
INSERT INTO quotes (id,text,occasion) VALUES (23,'Base concluída. Os alicerces da cidade dourada estão prontos — agora ergueremos os andares.','fase2');
INSERT INTO quotes (id,text,occasion) VALUES (24,'Você acabou de dominar a língua que a FUVEST fala. A partir de agora, só conversas difíceis.','fase2');
INSERT INTO quotes (id,text,occasion) VALUES (25,'Aprofundamento concluído. O nível da prova já não te assusta — você treinou acima dele.','fase3');
INSERT INTO quotes (id,text,occasion) VALUES (26,'Você mergulhou fundo onde a maioria boia. Por isso o topo é seu próximo endereço.','fase3');
INSERT INTO quotes (id,text,occasion) VALUES (27,'Nível FUVEST alcançado. Agora cada simulado é um ensaio geral, e você é a protagonista.','fase4');
INSERT INTO quotes (id,text,occasion) VALUES (28,'Você está a um passo do palco. Os 3 anos de treino viram 3 horas de espetáculo.','fase4');
INSERT INTO quotes (id,text,occasion) VALUES (29,'Fase final. O cronograma está no fim, mas a missão só está começando. Boa prova, Gabi.','fase5');
INSERT INTO quotes (id,text,occasion) VALUES (30,'Tudo que era para ser estudado, foi. Tudo que era para ser revisado, está. Agora a cidade assiste.','fase5');
INSERT INTO quotes (id,text,occasion) VALUES (31,'Patente promovida: Cadete. A cidade reconhece os primeiros passos.','rank:cadete');
INSERT INTO quotes (id,text,occasion) VALUES (32,'Patente promovida: Investigadora. Você já sabe onde procurar as respostas.','rank:investigadora');
INSERT INTO quotes (id,text,occasion) VALUES (33,'Patente promovida: Analista. Nenhum assunto escapa da sua análise.','rank:analista');
INSERT INTO quotes (id,text,occasion) VALUES (34,'Patente promovida: Especialista. Você é referência no distrito.','rank:especialista');
INSERT INTO quotes (id,text,occasion) VALUES (35,'Patente promovida: Elite. Os holofotes da cidade encontram você.','rank:elite');
INSERT INTO quotes (id,text,occasion) VALUES (36,'Patente promovida: Veterana. Os veteranos não tremem em dia de prova.','rank:veterana');
INSERT INTO quotes (id,text,occasion) VALUES (37,'Patente promovida: Operadora. A operação agora opera com você no comando.','rank:operadora');
INSERT INTO quotes (id,text,occasion) VALUES (38,'Patente máxima: Agente FMUSP. A torre já reservou sua cadeira.','rank:agente_fmusp');
