INSERT INTO exams (id,institution,name,year,questions_json,suggested_minutes) VALUES (1,'ENEM','Simulado de Exemplo — ENEM',2026,'[{"id": 1, "subject": "Matemática", "topic": "Probabilidade", "text": "Uma urna contém 4 bolas vermelhas e 6 bolas azuis. Retirando uma bola ao acaso, qual a probabilidade de ela ser vermelha?", "options": ["20%", "40%", "60%", "80%", "100%"], "answer": "B"}, {"id": 2, "subject": "Biologia", "topic": "Ecologia", "text": "Em uma cadeia alimentar, os organismos que produzem seu próprio alimento por fotossíntese são chamados de:", "options": ["Consumidores primários", "Decompositores", "Produtores", "Consumidores secundários", "Predadores de topo"], "answer": "C"}, {"id": 3, "subject": "Física", "topic": "Cinemática", "text": "Um carro parte do repouso com aceleração constante de 4 m/s². Qual a velocidade após 5 segundos?", "options": ["5 m/s", "10 m/s", "15 m/s", "20 m/s", "25 m/s"], "answer": "D"}, {"id": 4, "subject": "Química", "topic": "Estequiometria", "text": "Qual é a massa molar aproximada da água (H₂O)? Dados: H = 1 g/mol; O = 16 g/mol.", "options": ["16 g/mol", "17 g/mol", "18 g/mol", "19 g/mol", "20 g/mol"], "answer": "C"}, {"id": 5, "subject": "Português", "topic": "Interpretação de texto", "text": "Na frase ''A cidade acordou dourada esta manhã'', a palavra ''dourada'' tem função de:", "options": ["Substantivo", "Verbo", "Advérbio", "Adjetivo", "Pronome"], "answer": "D"}]',30);
